# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: run output lines (fixed columns, self-contained, journald-aware).

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    function Get-RunLines {
        # run the engine, return its narration lines (Information stream) as strings
        param($Config, $Paths, [switch]$Journal)
        $saved = $env:JOURNAL_STREAM
        $env:JOURNAL_STREAM = if ($Journal) { '8:1234' } else { $null }
        try {
            $out = Invoke-BackupRun -Config $Config -Paths $Paths -ForceWindow -InformationAction Continue -WarningAction SilentlyContinue 6>&1
            return @($out | Where-Object { $_ -is [System.Management.Automation.InformationRecord] } | ForEach-Object { [string]$_.MessageData })
        }
        finally { $env:JOURNAL_STREAM = $saved }
    }

    function Split-RunLine {
        # journal-mode line (no time column) -> service / step / event / status / detail by column
        param([string]$Line)
        $col = { param($from, $w) if ($Line.Length -gt $from) { $Line.Substring($from, [math]::Min($w, $Line.Length - $from)).Trim() } else { '' } }
        [pscustomobject]@{
            Id      = $Line.Substring(0, 4)
            Service = & $col 6 18
            Step    = & $col 26 12
            Event   = & $col 40 6
            Status  = & $col 48 4
            Detail  = if ($Line.Length -gt 62) { $Line.Substring(62) } else { '' }
        }
    }
}

AfterAll {
    Remove-TestWork
}

Describe 'run line format' {
    It 'lays out fixed columns, run id first, then time' {
        $t = [datetime]::new(2026, 11, 18, 23, 1, 9)
        Format-RunLine -RunId '20261118-230108-c583' -Time $t -Service 'forgejo' -Step 'dump' -Event 'end' -Status 'ok' -Duration '53m28s' -Detail 'from 23:01:34' |
            Should -Be 'c583  23:01:09  forgejo             dump          end     ok    53m28s  from 23:01:34'
    }

    It 'puts the outcome in its own column, after the event' {
        Format-RunLine -RunId 'r-c583' -Service 'forgejo' -Step 'dump' -Event 'end' -Status 'FAIL' -Duration '1m46s' -Detail 'from 23:01:24  ! tar exited with code 2' |
            Should -Be 'c583  forgejo             dump          end     FAIL  1m46s   from 23:01:24  ! tar exited with code 2'
        Format-RunLine -RunId 'r-c583' -Service 'forgejo' -Step 'dump' -Event 'msg' -Status 'WARN' -Detail 'file changed' |
            Should -Be 'c583  forgejo             dump          msg     WARN          file changed'
    }

    It 'drops the time column when no time is given (journald)' {
        Format-RunLine -RunId '20261118-230108-c583' -Service 'forgejo' -Step 'dump' -Event 'begin' |
            Should -Be 'c583  forgejo             dump          begin'
    }

    It 'defaults to the run-level service and step' {
        Format-RunLine -RunId 'x-c583' -Event 'end' -Status 'ok' -Duration '5.2s' -Detail '1 ok' |
            Should -Be 'c583  run                 -             end     ok    5.2s    1 ok'
    }

    It 'truncates long names with ~ and keeps columns aligned' {
        $a = Format-RunLine -RunId 'r-0001' -Service 'a-very-long-service-name' -Step 'a-very-long-step' -Event 'begin'
        $a | Should -Be '0001  a-very-long-servi~  a-very-long~  begin'
        $b = Format-RunLine -RunId 'r-0001' -Service 'x' -Step 'y' -Event 'begin'
        $a.IndexOf('begin') | Should -Be $b.IndexOf('begin')
    }

    It 'marks a line with no run as ----' {
        Format-RunLine -RunId '' -Event 'skip' -Status 'WARN' -Detail 'another run is in progress' |
            Should -Be '----  run                 -             skip    WARN          another run is in progress'
    }

    It 'gives the start reference with the date only when it was another day' {
        $now = [datetime]::new(2026, 11, 19, 0, 5, 49)
        Format-StartRef -Start ([datetime]::new(2026, 11, 19, 0, 1, 2)) -Now $now | Should -Be '00:01:02'
        Format-StartRef -Start ([datetime]::new(2026, 11, 18, 23, 1, 22)) -Now $now | Should -Be '11-18 23:01:22'
    }
}

Describe 'run narration' {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'ro'
        $script:paths = $t.Paths
    }

    It 'narrates each step start and end, tagged with service and step' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"dump"}, {"name":"chatty"} ] } } }
'@ | ConvertFrom-Json
        $lines = @(Get-RunLines $cfg $paths -Journal)
        $rows = @($lines | ForEach-Object { Split-RunLine $_ })
        $seq = @($rows | ForEach-Object { "{0}|{1}|{2}|{3}" -f $_.Service, $_.Step, $_.Event, $_.Status })
        $seq | Should -Be @(
            'run|-|begin|', 'app|-|begin|',
            'app|dump|begin|', 'app|dump|end|ok',
            'app|chatty|begin|', 'app|chatty|msg|WARN', 'app|chatty|msg|', 'app|chatty|msg|', 'app|chatty|end|ok',
            'app|-|end|ok', 'run|-|end|ok')
        ($rows | Where-Object { $_.Status -eq 'WARN' }).Detail | Should -Be 'chatty warning'
        @($rows | Where-Object { $_.Event -eq 'msg' -and -not $_.Status }).Detail | Should -Be @('chatty info', 'chatty host')
        $rows[3].Detail | Should -Match '^from \d\d:\d\d:\d\d$'          # end line repeats the start
        $rows[-2].Detail | Should -Match 'kept in ready/app'
        $rows[-1].Detail | Should -Be '1 ok, 0 failed, 1 planned'
        @($rows | Select-Object -ExpandProperty Id -Unique).Count | Should -Be 1   # every line carries the run id
        ($lines -join "`n") | Should -Not -Match 'chatty output object'   # step output objects stay dropped
    }

    It 'records step warnings in the event log and the email report, not info lines' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"dump"}, {"name":"chatty"} ] } } }
'@ | ConvertFrom-Json
        $null = Get-RunLines $cfg $paths -Journal
        $ends = @(Get-BackupEvents -EventsPath $paths.EventsPath | Where-Object { $_.type -eq 'step.end' })
        @($ends | Where-Object { $_.step -eq 'chatty' })[0].warnings | Should -Be @('chatty warning')
        Test-HasProp @($ends | Where-Object { $_.step -eq 'dump' })[0] 'warnings' | Should -BeFalse   # absent when none
        $runId = @(Get-BackupEvents -EventsPath $paths.EventsPath | Where-Object { $_.type -eq 'run.begin' })[0].runId
        $report = Format-RunReport -EventsPath $paths.EventsPath -RunId $runId
        $report | Should -Match '(?m)^  ! app\s+chatty: chatty warning$'
        $report | Should -Not -Match 'chatty info'
    }

    It 'shows a failed step, the recovery step, and the service failure' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
      "steps": [ {"name":"dump"}, {"name":"boom"}, {"name":"start", "alwaysRun": true} ] } } }
'@ | ConvertFrom-Json
        $rows = @(Get-RunLines $cfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $seq = @($rows | ForEach-Object { "{0}|{1}|{2}|{3}" -f $_.Service, $_.Step, $_.Event, $_.Status })
        $seq | Should -Be @(
            'run|-|begin|', 'app|-|begin|',
            'app|dump|begin|', 'app|dump|end|ok',
            'app|boom|begin|', 'app|boom|end|FAIL',
            'app|start|begin|', 'app|start|end|ok',
            'app|-|end|FAIL', 'run|-|end|FAIL')
        # the error sits after the start reference, behind its marker
        ($rows | Where-Object { $_.Step -eq 'boom' -and $_.Status -eq 'FAIL' }).Detail | Should -Match '^from \d\d:\d\d:\d\d  ! simulated failure$'
        ($rows | Where-Object { $_.Service -eq 'app' -and $_.Step -eq '-' -and $_.Status -eq 'FAIL' }).Detail | Should -Be '! step boom failed; partial dump discarded'
        # the event log carries the same: status + error on the closing events
        $evs = @(Get-BackupEvents -EventsPath $paths.EventsPath)
        $svcEnd = @($evs | Where-Object { $_.type -eq 'service.end' })[0]
        $svcEnd.status | Should -Be 'fail'
        $svcEnd.error | Should -Be 'step boom failed'
        @($evs | Where-Object { $_.type -eq 'run.end' })[0].status | Should -Be 'fail'
    }

    It 'shows a covered service as a skip line' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"dump"} ] } } }
'@ | ConvertFrom-Json
        Get-RunLines $cfg $paths -Journal | Out-Null
        $rows = @(Get-RunLines $cfg $paths -Journal | ForEach-Object { Split-RunLine $_ })
        $skip = $rows | Where-Object { $_.Service -eq 'app' }
        $skip.Event | Should -Be 'skip'
        $skip.Detail | Should -Match '^covered \(x0\.\d\d\)$'
    }

    It 'on a terminal: a date line first, then a time column on every line' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"dump"} ] } } }
'@ | ConvertFrom-Json
        $lines = @(Get-RunLines $cfg $paths)
        $lines[0] | Should -Match '^\d{4}-\d\d-\d\d -{10,}$'
        foreach ($l in ($lines | Select-Object -Skip 1)) { $l | Should -Match '^[0-9a-f]{4}  \d\d:\d\d:\d\d  ' }
    }

    It 'in the journal: no date line, no time column' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"dump"} ] } } }
'@ | ConvertFrom-Json
        $lines = @(Get-RunLines $cfg $paths -Journal)
        $lines[0] | Should -Match '^[0-9a-f]{4}  run {17}-'
        ($lines -join "`n") | Should -Not -Match '\d\d:\d\d:\d\d  (run|app) '
    }

    It 'asks tools for plain output during the run, and restores the environment after' {
        $env:COMPOSE_PROGRESS = 'auto'
        try {
            $cfg = @'
{ "window": { "open": "00:00", "close": "00:01" },
  "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "publishToReady": true,
      "steps": [ {"name":"envcheck"} ] } } }
'@ | ConvertFrom-Json
            $lines = @(Get-RunLines $cfg $paths -Journal)
            ($lines -join "`n") | Should -Match 'tool env: NO_COLOR=1 COMPOSE_ANSI=never COMPOSE_PROGRESS=plain'
            $env:COMPOSE_PROGRESS | Should -Be 'auto'
        }
        finally { $env:COMPOSE_PROGRESS = $null }
    }
}
